ius:10px;background:rgba(255,255,255,.04);font-size:18px;color:#d9e8e1;transition:.2s}.icon-btn:hover{background:rgba(124,224,187,.16);border-color:rgba(124,224,187,.5);color:var(--teal)}.status-card{position:absolute;top:91px;left:25px;width:256px;padding:15px 16px 14px;border-radius:13px}.profile{display:flex;align-items:center;gap:10px;padding-bottom:12px;border-bottom:1px solid var(--line)}.avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(145deg,#2c5951,#24443e);color:#aff0d2;font:600 16px var(--display)}.profile>div:nth-child(2){flex:1}.profile b{font:600 10px var(--mono);letter-spacing:.07em}.profile small{display:block;margin-top:4px;color:#92a19e;font:9px var(--mono);letter-spacing:.08em}.level{font:9px var(--mono);color:#8f9e99}.level b{display:block;color:var(--gold);font-size:13px;text-align:right;margin-top:3px}.needs{display:grid;gap:10px;padding:13px 0}.need-label{display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;font:9px var(--mono);letter-spacing:.08em;color:#9daaa6}.need-label b{color:#dfe9e3;font-weight:500}.meter{height:4px;background:rgba(255,255,255,.1);border-radius:5px;overflow:hidden}.meter i{height:100%;display:block;border-radius:5px;transition:width .3s}.energy{background:#e5ca76}.hunger{background:#ef9c73}.thirst{background:#83bce3}.wallet{padding-top:10px;border-top:1px solid var(--line)}.wallet small{display:block;color:#9ba9a4;font:9px var(--mono);letter-spacing:.11em}.wallet>b{display:block;margin-top:3px;font:600 24px var(--display);letter-spacing:-.03em}.wallet>b span{color:var(--teal);font-size:18px;margin-right:2px}.wallet>b i{font-style:normal}.wallet .bank{display:flex;gap:5px;margin-top:7px;font-size:8px}.wallet .bank strong{color:#d6e5dc;font-weight:500}.right-rail{position:absolute;right:24px;top:93px;width:224px;display:grid;gap:10px}.rail-title{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spa