rder-top:1px solid rgba(255,255,255,.06)}.controls-hint{display:flex;gap:17px;color:#a7b3ae;font:8px var(--mono);letter-spacing:.07em}.controls-hint span{display:flex;align-items:center;gap:4px}.controls-hint kbd{height:15px;min-width:15px;font-size:8px}.bottom-right{display:flex;align-items:center;gap:14px;color:#9caca4;font:8px var(--mono);letter-spacing:.12em}.sound-bars{height:15px;display:flex;align-items:center;gap:2px}.sound-bars i{display:block;width:2px;height:5px;border-radius:2px;background:#79dbb5;animation:sound 1s ease-in-out infinite alternate}.sound-bars i:nth-child(2){height:11px;animation-delay:.3s}.sound-bars i:nth-child(3){height:8px;animation-delay:.6s}.sound-bars i:nth-child(4){height:13px;animation-delay:.2s}@keyframes sound{to{height:3px;opacity:.5}}.hidden{display:none!important}.toast-stack{position:absolute;top:82px;left:50%;transform:translateX(-50%);display:grid;gap:7px;pointer-events:none}.toast{padding:10px 15px;border:1px solid rgba(124,224,187,.23);border-radius:8px;background:rgba(13,25,29,.93);color:#dce9e1;font:10px var(--mono);box-shadow:0 8px 25px #0005;animation:toastIn .25s ease-out}.toast b{color:var(--teal)}@keyframes toastIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}.modal-backdrop,.map-overlay,.help-overlay{position:absolute;inset:0;display:grid;place-items:center;padding:18px;background:rgba(4,11,13,.63);backdrop-filter:blur(6px)}.modal{position:relative;width:min(470px,calc(100vw - 32px));max-height:88vh;overflow:auto;padding:30px;border-radius:17px;animation:modalIn .22s ease-out}.modal-close{position:absolute;right:15px;top:13px;width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--line);border-radius:8px;background:rgba(255,255,255,.04);font-size:19px;color:#aebbb4}.modal-eyebrow{color:var(--teal);font:9px var(--mono);letter-spacing:.16em}.modal h1,.help-card h1{margin:9px 0 7px;font:600 27px var(--display);letter-spacing:-.04em}.modal>p,.help-card>p{margin:0 0 21px