nd:#86bfe8}.help-overlay{z-index:7}.help-card{position:relative;width:min(510px,calc(100vw - 32px));padding:32px;border-radius:18px;animation:modalIn .25s ease-out}.help-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px 18px;margin:20px 0 5px}.help-grid article{position:relative;padding-left:28px}.help-grid article>span{position:absolute;left:0;top:1px;color:var(--teal);font:10px var(--mono)}.help-grid article b{font:600 11px var(--display)}.help-grid article p{margin:5px 0 0;color:#9eada7;font-size:10px;line-height:1.5}@keyframes modalIn{from{opacity:0;transform:translateY(10px) scale(.99)}to{opacity:1;transform:none}}@media(max-width:760px){.topbar{height:59px;padding:0 14px}.brand{font-size:12px}.brand-mark{width:29px;height:29px}.location{top:64px;left:14px;transform:none;padding:7px 9px;border-radius:7px;background:rgba(13,25,29,.75)}.location b{font-size:8px}.location small{font-size:7px}.status-card{top:105px;left:10px;width:188px;padding:11px}.profile{gap:7px}.avatar{width:29px;height:29px}.profile b{font-size:8px}.profile small,.level{font-size:7px}.needs{gap:8px;padding:10px 0}.need-label{font-size:8px}.wallet>b{font-size:20px}.right-rail{right:10px;top:105px;width:158px;gap:7px}.city-map{padding:6px}.city-map canvas{height:87px}.map-caption{font-size:7px}.weather{padding:8px;gap:7px}.weather-temp{display:none}.weather small{font-size:6px}.weather b{font-size:10px}.weather b span{display:block;margin-top:2px}.weather-icon{width:27px;height:27px}.nearby{padding:9px}.nearby-row{gap:6px}.nearby-row small{font-size:7px}.nearby-row b{font-size:9px}.nearby-icon{width:22px;height:22px}.objective{left:10px;bottom:61px;width:min(285px,calc(100vw - 20px));padding:10px 32px 10px 11px}.objective p{font-size:9px}.objective b{font-size:11px}.bottom-bar{height:43px;padding:0 10px}.controls-hint{gap:8px;font-size:7px}.controls-hint span{gap:2px}.controls-hint span:nth-child(3){display:none}.controls-hint kbd{height:14px;min-width:14px;font-size:7px}.bottom-right{font-size:7px}.vehicle-hud{right:10px;bottom:112px;min-width:190px;padding:9px}.interact-prompt{bottom:111px}.map-legend{gap:9px;font-size:7px;flex-wrap:wrap}.map-legend span:last-child{margin-left:0}.help-card{padding:25px 20px}.help-card h1{font-size:23px}.help-grid{gap:11px}.help-grid article{padding-left:23px}.help-grid article p{font-size:9px}.modal{padding:25px 20px}.modal h1{font-size:23px}}

