function money(n){return '$'+Math.round(n).toLocaleString('en-US')}
function changeCash(n){state.cash+=n;updateHUD()}
function addXP(n){state.xp+=n;if(state.xp>=state.level*180){state.xp-=state.level*180;state.level++;toast('LEVEL UP <b>· You reached level '+state.level+'</b>');}updateHUD()}
