 for(let k=0;k<4;k++){const w=75+rnd()*72,h=62+rnd()*65,x=bx+18+rnd()*Math.max(1,bw-w-30),y=by+10+rnd()*Math.max(1,bh-h-25);if(!services.some(s=>x<s.x+s.w+30&&x+w>s.x-30&&y<s.y+s.h+28&&y+h>s.y-28))filler.push({x,y,w,h,color:['#786f65','#777b6b','#806f69','#6f7a72','#887866'][Math.floor(rnd()*5)],roof:['#a99579','#918774','#7c8475','#a37d6a'][Math.floor(rnd()*4)]})}
}
const trees=[];for(let i=0;i<180;i++){const x=rnd()*W,y=rnd()*H;if(roadsX.some(rx=>Math.abs(rx-x)<72)||roadsY.some(ry=>Math.abs(ry-y)<60))continue;trees.push({x,y,r:5+rnd()*6,shade:rnd()})}
const people=Array.from({length:22},(_,i)=>({x:100+rnd()*(W-200),y:100+rnd()*(H-200),phase:rnd()*9,speed:.1+rnd()*.3,color:['#d8aa7b','#8ac4a9','#db9580','#92a9cb'][i%4]}));
