 // green pockets and plazas
 for(const p of [{x:900,y:740,w:250,h:65},{x:1850,y:735,w:270,h:70},{x:760,y:1180,w:240,h:250},{x:1480,y:1220,w:230,h:190}]){ctx.fillStyle='#405a48';ctx.fillRect(p.x,p.y,p.w,p.h);ctx.fillStyle='rgba(166,181,125,.12)';ctx.fillRect(p.x+8,p.y+8,p.w-16,p.h-16)}
