 // paths through parks
 ctx.strokeStyle='#aa9c81';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(760,1295);ctx.lineTo(1000,1295);ctx.moveTo(880,1180);ctx.lineTo(880,1430);ctx.moveTo(1480,1300);ctx.lineTo(1710,1300);ctx.stroke();
